<?php
declare(strict_types=1); require_once __DIR__.'/finance.php'; require_finance_admin();$month=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['month']??''))?(string)$_GET['month']:date('Y-m');$from=$month.'-01';$to=date('Y-m-d',strtotime($from.' +1 month'));$stmt=db()->prepare('SELECT date,transaction_type,category,description,money_in,money_out,reference,running_balance FROM cash_flow WHERE date>=? AND date<? ORDER BY date,id');$stmt->execute([$from,$to]);$rows=$stmt->fetchAll();if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="finance-'.$month.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','Type','Category','Description','Money In','Money Out','Reference','Running Balance']);foreach($rows as $row)fputcsv($out,$row);exit;}if(($_GET['export']??'')==='xls'){header('Content-Type:application/vnd.ms-excel');header('Content-Disposition:attachment; filename="finance-'.$month.'.xls"');echo "Date\tType\tCategory\tDescription\tMoney In\tMoney Out\tReference\tRunning Balance\n";foreach($rows as $row)echo implode("\t",array_map(fn($v)=>str_replace(["\t","\n"],' ',(string)$v),$row))."\n";exit;}function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><title>Finance Export</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><main class="saas-main"><h1 class="saas-title">Finance Export</h1><a class="btn-indigo" href="finance_report.php?month=<?=e($month)?>&export=xls">Excel</a> <a class="btn-outline-indigo" href="finance_report.php?month=<?=e($month)?>&export=csv">CSV</a> <button class="btn-outline-indigo" onclick="window.print()">Print / Save PDF</button><table class="saas-table"><tr><th>Date</th><th>Type</th><th>Category</th><th>Description</th><th>In</th><th>Out</th><th>Balance</th></tr><?php foreach($rows as $row):?><tr><td><?=e($row['date'])?></td><td><?=e($row['transaction_type'])?></td><td><?=e($row['category'])?></td><td><?=e($row['description'])?></td><td><?=inr($row['money_in'])?></td><td><?=inr($row['money_out'])?></td><td><?=inr($row['running_balance'])?></td></tr><?php endforeach;?></table></main></body></html>
